prog='''from collections import deque,Counter
def transform(g):
    h,w=len(g),len(g[0])
    vals=Counter(v for row in g for v in row)
    line=max(vals,key=vals.get)  # background = most common
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==line and not seen[r][c]: seen[r][c]=True;q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==line and not seen[r][c]: seen[r][c]=True;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==line and not seen[nr][nc]:
                seen[nr][nc]=True;q.append((nr,nc))
    out=[[4 if g[r][c]==line and not seen[r][c] else g[r][c] for c in range(w)] for r in range(h)]
    def hole(r,c):
        return 0<=r<h and 0<=c<w and g[r][c]==line and not seen[r][c]
    # quirk from demos: a 2-row-tall enclosed pocket also recolors the cell row directly below it
    for c in range(w):
        for r in range(1,h-2):
            if hole(r,c) and hole(r+1,c) and not hole(r-1,c) and not hole(r+2,c):
                out[r+2][c]=4
    return out
'''
